(() => {
  const q = (id, topic, type, prompt, options, answer, why, wrong, remember, caseStudy) => ({ id, topic, type, prompt, options, answer, why, wrong, remember, source: 'manage', ...(caseStudy ? { caseStudy } : {}) });
  const retail = { title: 'Case study: Adventure Works Retail', intro: 'Adventure Works has a central BI team that builds reports in a workspace. Sales employees should consume a polished set of reports but must not edit workspace content. Regional managers must see only their own region’s sales. The source database is on-premises SQL Server, and the semantic model must refresh nightly.' };
  window.MANAGE_QUESTION_BANK = [
    q('g01','Workspaces','Choose ONE','A small BI team needs a shared place to create, collaborate on, and organize reports, dashboards, and semantic models. What should they create?', ['A workspace','A dashboard','A data alert','A report subscription'], 'A', 'A workspace is the collaborative container for Power BI content and team access roles.', 'A dashboard is a single-page consumption surface. Alerts and subscriptions notify users but do not organize build content.', 'Build and collaborate on Power BI items → workspace.'),
    q('g02','Workspace roles','Choose ONE','A business user must view and interact with content in a workspace but must not edit or publish items. Which workspace role is best?', ['Viewer','Contributor','Member','Admin'], 'A', 'Viewer grants consumption access without the ability to create or modify workspace content.', 'Contributor, Member, and Admin are authoring or management roles with more capability than required.', 'Consumers in a workspace normally need Viewer.'),
    q('g03','Workspace roles','Choose ONE','An analyst must create and edit reports in a workspace but should not manage workspace access or publish the organizational app. Which role is the best fit?', ['Contributor','Viewer','Admin','Fabric administrator'], 'A', 'Contributor supports creating and editing workspace content without the broader workspace management responsibility of Admin.', 'Viewer cannot create content. Admin has more rights than necessary. A Fabric administrator is a tenant-wide role.', 'Give authors the least powerful workspace role that lets them build.'),
    q('g04','Workspace roles','Choose ONE','Who can manage workspace access, settings, and the workspace itself?', ['Workspace Admin','Viewer','Report consumer','Semantic model Build user only'], 'A', 'The Admin role has full workspace management responsibilities, including access management and settings.', 'The other options do not manage the workspace as a whole.', 'Workspace governance responsibility → Admin.'),
    q('g05','Apps','Choose ONE','A finance team needs a polished, read-only experience with a branded landing page and a stable link for hundreds of business consumers. The report authors should continue working separately. What is the best distribution method?', ['Publish a Power BI app from the workspace.','Add every consumer as a workspace Contributor.','Email PBIX files to consumers.','Share the workspace Admin link.'], 'A', 'An app packages selected workspace content for consumption and can target audiences. It separates builder collaboration from consumer access.', 'Contributor and Admin grant excessive rights. PBIX email copies are hard to govern.', 'Builders use the workspace; broad consumers use an app.'),
    q('g06','Apps','Choose TWO','A published app has Sales Leadership and Store Managers audiences. Which TWO capabilities can app audiences provide?', ['Show different app content to different groups.','Control which groups can access the app.','Make every audience a workspace Admin.','Replace row-level security automatically.','Turn Import models into DirectQuery.'], 'A and B', 'App audiences control access and can tailor which content each group sees. They do not replace data security such as RLS.', 'Workspace Admin, automatic RLS, and storage mode changes are unrelated to app audiences.', 'Apps distribute the right content to the right consumer audience.'),
    q('g07','Publishing items','Choose ONE','You edited a PBIX file in Power BI Desktop and need the changed report and semantic model available in an existing service workspace. What should you do?', ['Publish the updated PBIX to that workspace and confirm the replacement prompt.','Create a dashboard alert.','Export the report to PDF.','Assign every user the Admin role.'], 'A', 'Publishing the updated file to the same workspace updates the matching Power BI items in the service after confirmation.', 'Alerts, PDF export, and roles do not update workspace content.', 'Desktop changes reach the service through publishing to the intended workspace.'),
    q('g08','Updating apps','Choose ONE','A report in a workspace has been updated, but app users still see the older app version. What is the required next step?', ['Update or republish the app.','Refresh the user browser only.','Create a new workspace.','Change the report theme.'], 'A', 'Workspace content changes are not automatically the same as an app release. Update the app to publish the revised consumer package.', 'Browser refresh and theme changes do not release a new app version.', 'Workspace edit complete? Update the app for consumers.'),
    q('g09','Dashboards','Choose ONE','An executive wants one single-page canvas of important KPI tiles, each of which can link back to a supporting report. What should you create?', ['A dashboard','A dataflow','A calculation group','A workspace role'], 'A', 'A dashboard is a single-page collection of tiles, often pinned from report visuals, intended for at-a-glance monitoring.', 'Dataflows transform data, calculation groups transform measures, and roles control access.', 'Single-page KPI tile experience → dashboard.'),
    q('g10','Data alerts','Choose ONE','A manager needs an email when a dashboard KPI tile rises above 95%. Which setup is required?', ['Create a data alert on a dashboard KPI, gauge, or card tile.','Add conditional formatting to a report table.','Create a page bookmark.','Schedule a report subscription only.'], 'A', 'Data alerts are configured on eligible dashboard tiles such as KPI, gauge, and card tiles. They are evaluated when data refreshes.', 'Conditional formatting changes appearance; bookmarks save state; subscriptions are scheduled rather than threshold-based.', 'Threshold notification → alert on an eligible dashboard tile.'),
    q('g11','Subscriptions','Choose ONE','Executives need a report snapshot and link delivered to their inbox every Monday morning whether or not a threshold is crossed. What should you configure?', ['An email subscription','A data alert','A row-level security role','A calculation group'], 'A', 'An email subscription sends a report or dashboard on a schedule. It is different from a data alert, which triggers after data crosses a rule threshold.', 'RLS controls data visibility and calculation groups change measures.', 'Scheduled delivery → subscription; threshold event → alert.'),
    q('g12','Endorsement','Choose ONE','A report owner wants to signal that a report is useful and recommended for colleagues. The owner has write permission but is not an authorized organization certifier. Which endorsement can they apply?', ['Promoted','Certified','Sensitivity labeled only','Archived'], 'A', 'Content owners with appropriate write permission can promote valuable content. Certification is reserved for reviewers authorized by the Power BI administrator.', 'Certification requires authorization. Labels serve classification, not endorsement.', 'Promoted = useful recommendation; certified = organization-approved authority.'),
    q('g13','Endorsement','Choose ONE','A semantic model must be marked as authoritative and approved against the organization’s quality standards. Who can certify it?', ['An authorized reviewer designated by the Power BI administrator.','Any report Viewer.','Any user who has Read permission.','Only an external guest user.'], 'A', 'Certification is a governed endorsement that only authorized reviewers can apply.', 'Read and Viewer permissions do not grant certification authority.', 'Certification is controlled by the organization, not self-declared.'),
    q('g14','Gateways','Choose ONE','A semantic model in the Power BI service imports data from an on-premises SQL Server that cannot be reached directly from the cloud service. What is required for scheduled refresh?', ['An on-premises data gateway configured for the source.','A dashboard tile.','A report theme.','A calculation group.'], 'A', 'A gateway provides the secure bridge from the cloud service to reachable on-premises data sources for refresh or DirectQuery scenarios.', 'Dashboard design and model calculations do not provide network connectivity.', 'Cloud service needs on-premises source access → gateway.'),
    q('g15','Gateways','Choose ONE','A semantic model imports data only from SharePoint Online and Azure SQL Database, both reachable as cloud services with supported credentials. Is an on-premises data gateway normally required?', ['No, a gateway is normally not required for these cloud sources.','Yes, every scheduled refresh requires a gateway.','Yes, but only for report consumers.','No, because scheduled refresh cannot be used with cloud data.'], 'A', 'Cloud sources that the Power BI service can access directly normally do not need an on-premises gateway.', 'Gateways are not a universal refresh requirement, and cloud sources can be refreshed.', 'Gateway need depends on where and how the source is reachable.'),
    q('g16','Scheduled refresh','Choose ONE','After publishing an Import semantic model, data does not change until a refresh occurs. Where do you configure the recurring service refresh schedule?', ['The semantic model settings in the Power BI service.','The report’s Selection pane.','A visual tooltip.','The workspace app audience.'], 'A', 'Scheduled refresh is configured in the semantic model’s service settings, along with source credentials and gateway association where needed.', 'The other features control report design or distribution.', 'Refresh schedule belongs to the semantic model, not an individual visual.'),
    q('g17','Scheduled refresh','Choose ONE','A scheduled refresh fails with invalid credentials after the source password changes. What should you update?', ['The semantic model data-source credentials in the service.','The report page size.','The app audience label.','The DAX measure format.'], 'A', 'A password change invalidates stored source credentials, so update the connection credentials in the semantic model settings.', 'Report design, app labeling, and measure formatting do not authenticate to the source.', 'Refresh authentication failure → check semantic model credentials.'),
    q('g18','Semantic model access','Choose ONE','A user must create their own report and Excel PivotTable using an approved semantic model. Which permission is required in addition to access where applicable?', ['Build permission on the semantic model.','Viewer access to any unrelated workspace.','A dashboard subscription.','Sensitivity label owner.'], 'A', 'Build permission allows users to discover and create new content from a semantic model, including reports and Analyze in Excel scenarios.', 'Subscriptions and labels do not permit building against a model.', 'Reuse a semantic model to build new content → Build permission.'),
    q('g19','Semantic model access','Choose ONE','A user can view an existing shared report but should not create new reports from its semantic model. Which approach is most appropriate?', ['Grant report access without granting Build permission.','Make the user a workspace Admin.','Grant Build and Contributor permissions.','Publish the PBIX to the user.'], 'A', 'Report access enables consumption. Withholding Build prevents the intended self-service reuse permission.', 'Admin, Contributor, Build, and a PBIX copy grant more capability than required.', 'Consume a report without authoring → do not grant Build.'),
    q('g20','Item-level access','Choose ONE','A contractor should access one specific report but must not browse or collaborate on other workspace items. What should you configure?', ['Direct item-level access to that report, with only needed semantic model permissions.','Workspace Admin access.','A Contributor role.','An app audience that includes every workspace item.'], 'A', 'Item-level sharing scopes access to the specific report and can be paired with the minimum semantic-model access needed for it to work.', 'Workspace roles and an all-content audience are broader than requested.', 'Narrow audience to one item → item-level access.'),
    q('g21','Row-level security','Choose ONE','A Sales table has a Region column. Every user in the Regional Managers RLS role must see only rows where Sales[Region] equals their assigned region. What is the purpose of the RLS role?', ['Filter data rows for role members when they view the model through supported consumption access.','Hide report pages from all users.','Grant Build permission.','Refresh the semantic model nightly.'], 'A', 'Row-level security applies DAX filters to restrict which rows a role member can see. It is data security, not report layout or refresh configuration.', 'Pages, Build, and refresh solve different problems.', 'RLS controls which data rows a consumer can see.'),
    q('g22','Row-level security','Choose ONE','You define an RLS role in Power BI Desktop. What must happen after publishing before users are restricted in the Power BI service?', ['Assign users or a security group to the role in the semantic model security settings.','Create a dashboard from the report.','Make every user a workspace Admin.','Export the model to Excel.'], 'A', 'Role rules define the filter, but service membership determines which users receive that filter after publication.', 'Dashboards, Admin roles, and Excel export do not assign RLS membership.', 'RLS requires both a rule and the right members.'),
    q('g23','Row-level security','Choose ONE','Which workspace role is the appropriate choice for users who must be subject to RLS filtering when consuming a workspace report?', ['Viewer','Admin','Member','Contributor'], 'A', 'RLS is intended to restrict consuming users. Workspace roles with edit permissions, such as Admin, Member, and Contributor, are not restricted by RLS in the same way as Viewers.', 'Authoring roles have broad content access and are unsuitable for RLS-restricted consumers.', 'RLS consumers should normally be Viewers, not workspace editors.'),
    q('g24','Row-level security','Choose TWO','Why is using a Microsoft Entra security group for RLS role membership often preferable to adding people one by one?', ['Membership can be managed centrally.','The same group can be reused for other access controls.','It changes the DAX filter automatically to allow all data.','It makes every user a workspace Admin.','It removes the need to publish the model.'], 'A and B', 'Security groups centralize membership and can be reused for workspace, app, and security administration patterns. The RLS filter itself remains defined by the role.', 'Groups do not grant Admin automatically, bypass filtering, or remove publication requirements.', 'Groups simplify membership management; they do not replace security design.'),
    q('g25','Sensitivity labels','Choose ONE','A report contains confidential payroll information. Your organization uses Microsoft Information Protection labels to classify and protect sensitive data. What should you apply?', ['An appropriate sensitivity label.','A promoted endorsement only.','A dashboard alert.','A calculation group.'], 'A', 'Sensitivity labels classify and help protect sensitive Power BI content according to organizational policy.', 'Promotion signals usefulness, while alerts and calculation groups are unrelated to information protection.', 'Data classification and protection requirement → sensitivity label.'),
    q('g26','Distribution methods','Choose ONE','A single colleague needs quick access to a draft report for feedback. The report is not a finalized organizational package. What is the most direct distribution method?', ['Share the specific report with that colleague.','Publish an enterprise-wide app audience.','Add the colleague as workspace Admin.','Email the PBIX as the only controlled option.'], 'A', 'Direct report sharing is appropriate for a narrow, specific sharing need. An app is more suitable for a curated broad audience.', 'Admin is excessive, and emailing PBIX creates unmanaged copies.', 'One person, one draft report → share the report with minimal access.'),
    q('g27','Case study: Adventure Works Retail','Choose TWO','Adventure Works wants Sales employees to consume a polished package without editing workspace content. Regional managers must see only their own region. Which TWO actions should you take?', ['Publish an app for the Sales audience.','Assign regional managers to an RLS role or security group.','Make all Sales employees workspace Contributors.','Grant every employee Build permission.','Set every workspace relationship to bidirectional.'], 'A and B', 'An app provides curated consumer distribution, while RLS restricts the rows visible to the assigned regional managers.', 'Contributor and Build grant authoring/reuse capability beyond simple consumption. Relationships do not enforce user data security.', 'App handles distribution; RLS handles per-user data visibility.', retail),
    q('g28','Case study: Adventure Works Retail','Choose ONE','Using the Adventure Works scenario, what is needed to refresh the on-premises SQL Server data nightly after the model is published?', ['Configure an on-premises data gateway, source credentials, and scheduled refresh for the semantic model.','Pin the report to a dashboard.','Add a data alert to a card.','Publish a new app every night.'], 'A', 'The gateway reaches the on-premises source, credentials authenticate, and the semantic model schedule runs the recurring refresh.', 'Dashboards, alerts, and app publication do not move data from the source into the model.', 'On-premises scheduled refresh = gateway + credentials + semantic model schedule.', retail),
    q('g29','Data alerts and RLS','Choose ONE','A regional manager creates a data alert on a dashboard KPI tile. How is the alert evaluated when RLS applies?', ['Against the data the manager is authorized to see.','Against all organization data regardless of RLS.','Only after an app is republished.','Only for report table visuals.'], 'A', 'Data alerts respect RLS, so the condition is evaluated using the data available to the user who created the alert.', 'RLS is not bypassed by alerts. Alerts work on eligible dashboard tiles, not report tables.', 'Alerts respect the creator’s data access context.'),
    q('g30','Workspace configuration','Choose ONE','You need to add a Microsoft Entra security group to a workspace so its members can view reports but not edit content. Which action is correct?', ['Add the group to workspace access as Viewer.','Add the group as Admin.','Grant every member Build permission only.','Create a dashboard tile for the group.'], 'A', 'Workspace access supports assigning security groups to a role. Viewer gives the requested consumption-only workspace access.', 'Admin is excessive, Build alone is not workspace access, and tiles do not assign permissions.', 'Use groups with the least-privilege workspace role.')
  ];
})();
